package main
import("encoding/json";"fmt";"os";"os/exec";"time")
type Job struct{DelaySeconds int `json:"delay_seconds"`;Command []string `json:"command"`}
func validate(jobs []Job)error{if len(jobs)<1||len(jobs)>100{return fmt.Errorf("use 1..100 jobs")};for _,j:=range jobs{if j.DelaySeconds<0||j.DelaySeconds>86400||len(j.Command)<1||j.Command[0]==""{return fmt.Errorf("invalid delay or command")}};return nil}
func main(){if len(os.Args)!=2||os.Args[1]=="--help"{fmt.Println("app JOBS.json\nExplicitly executes trusted command argument arrays after delays from program start. Foreground only. Maximum 100 jobs, 24 hours, one execution at a time.");if len(os.Args)!=2{os.Exit(2)};return};b,e:=os.ReadFile(os.Args[1]);if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)};var jobs []Job;if e=json.Unmarshal(b,&jobs);e==nil{e=validate(jobs)};if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)};start:=time.Now();pending:=append([]Job(nil),jobs...);failed:=false;for len(pending)>0{index:=0;for i:=range pending{if pending[i].DelaySeconds<pending[index].DelaySeconds{index=i}};j:=pending[index];pending=append(pending[:index],pending[index+1:]...);if wait:=time.Until(start.Add(time.Duration(j.DelaySeconds)*time.Second));wait>0{time.Sleep(wait)};fmt.Fprintf(os.Stderr,"Starting %q\n",j.Command);cmd:=exec.Command(j.Command[0],j.Command[1:]...);cmd.Stdout=os.Stdout;cmd.Stderr=os.Stderr;if e=cmd.Run();e!=nil{failed=true;fmt.Fprintln(os.Stderr,e)}};if failed{os.Exit(1)}}
